using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: discriminator property renamed from "Discriminator" to "$type".
        // Revert to EF8 name so existing 500K documents remain queryable without migration.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // EF Core 9 breaking change: id format changed from "EntityType|Key" to just "Key".
        // Preserve EF8 id format so existing documents (e.g. "Product|123") are still found.
        modelBuilder.Entity<Product>().HasKey(p => p.Id);
        modelBuilder.Entity<Product>().Property(p => p.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        // EF Core 9 removed support for client-side evaluation of Distinct/indexes in Cosmos.
        // Remove unsupported HasIndex call (Cosmos doesn't use EF-managed indexes).
        // Cosmos indexing is configured via the Azure portal or SDK indexing policy.
        modelBuilder.Entity<Product>().ToContainer("Products");
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } = "";

}

