class CosmosQuery
{
    // EF Core 9 breaking change: synchronous I/O is no longer supported for Cosmos.
    // All queries must use async APIs (ToListAsync, FirstOrDefaultAsync, etc.).
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we kept "Discriminator" as the property name
        // in OnModelCreating. Without that override, EF9 would use "$type" and this query would
        // return zero results against the existing 500K documents.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // Sync .ToList() replaced with async — EF Core 9 Cosmos throws at runtime on sync calls.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

